// Corre una vez para todos los items. Arma el HTML del digest.
const leads = $('Get Leads').all().map(i => i.json).filter(l => l.id);
const agencies = $('Get Agencies').all().map(i => i.json).filter(a => a.id);
const today = new Date().toISOString().slice(0, 10);

const ready = leads.filter(l => l.status === 'Ready');
const followups = leads.filter(l => l.next_action_date && l.next_action_date <= today && !['Won','Lost','Dormant','Ready','New'].includes(l.status));
const agFollow = agencies.filter(a => a.followup_date && a.followup_date <= today && !['Dead','Test project'].includes(a.status));

const esc = s => String(s || '').replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;');
const blue = '#1C5DEA', ink = '#05070D', paper = '#F3F5F9';

let html = `<div style="font-family:Inter,Arial,sans-serif;background:${paper};padding:24px;color:${ink}">`;
html += `<h2 style="font-weight:200;letter-spacing:-0.02em">POWER<strong style="font-weight:900">FLOW</strong><span style="color:${blue}">.</span> Lista de esta noche</h2>`;

html += `<p style="font-size:14px">Total: <b>${ready.length}</b> drafts por enviar, <b>${followups.length}</b> follow-ups, <b>${agFollow.length}</b> agencias.</p>`;

if (ready.length) {
  html += `<h3 style="margin-top:24px">1. Enviar estos drafts (${ready.length})</h3>`;
  for (const l of ready) {
    html += `<div style="background:#fff;border:1px solid #ECEEF3;border-radius:12px;padding:16px;margin:8px 0">`;
    html += `<b>${esc(l.name)}</b> · ${esc(l.role)} · ${esc(l.company)} <a href="${esc(l.linkedin_url)}" style="color:${blue}">perfil</a>`;
    html += `<p style="white-space:pre-wrap;font-size:14px;margin:8px 0 0">${esc(l.draft_msg)}</p></div>`;
  }
}

if (followups.length) {
  html += `<h3 style="margin-top:24px">2. Follow-ups de hoy (${followups.length})</h3>`;
  for (const l of followups) {
    html += `<div style="background:#fff;border:1px solid #ECEEF3;border-radius:12px;padding:16px;margin:8px 0">`;
    html += `<b>${esc(l.name)}</b> · ${esc(l.company)} · status: ${esc(l.status)}<br/>`;
    html += `<span style="font-size:13px">Acción: ${esc(l.next_action || 'follow up')}</span>`;
    if (l.draft_msg) html += `<p style="white-space:pre-wrap;font-size:14px;margin:8px 0 0">${esc(l.draft_msg)}</p>`;
    html += `</div>`;
  }
}

if (agFollow.length) {
  html += `<h3 style="margin-top:24px">3. Agencias (${agFollow.length})</h3><ul>`;
  for (const a of agFollow) html += `<li>${esc(a.agency)} · ${esc(a.contact_name)} · ${esc(a.email)}</li>`;
  html += `</ul>`;
}

if (!ready.length && !followups.length && !agFollow.length) {
  html += `<p>Nada pendiente del sistema hoy. Cargá 10 prospectos nuevos o mandá 3 DMs manuales. Un mensaje. Una persona. Un día a la vez.</p>`;
}

html += `</div>`;
return [{ json: { html, subject: `Power Flow: ${ready.length} drafts + ${followups.length + agFollow.length} follow-ups` } }];
